DO $$ DECLARE d text; BEGIN
 SELECT pg_get_functiondef('public.guard_paid_challenge_join()'::regprocedure) INTO d;
 d:=replace(d,'IF NEW.source=''order'' AND NOT EXISTS','IF NEW.access_status=''active'' AND NEW.source=''order'' AND NOT EXISTS');
 d:=replace(d,'IF EXISTS(SELECT 1 FROM challenges WHERE id=NEW.challenge_id AND is_paid)','IF NEW.access_status=''active'' AND EXISTS(SELECT 1 FROM challenges WHERE id=NEW.challenge_id AND is_paid)'); EXECUTE d;
 SELECT pg_get_functiondef('public.record_unallocated_challenge_refund(uuid,text,integer,text)'::regprocedure) INTO d;
 d:=replace(d,'IF _status=''succeeded'' THEN UPDATE orders SET status=''disputed'',updated_at=now() WHERE id=_order AND status IN(''paid'',''partially_refunded''); END IF;',''); EXECUTE d;
 SELECT pg_get_functiondef('public.reconcile_challenge_order(uuid,text,text,integer,text,text,text)'::regprocedure) INTO d;
 d:=replace(d,'OR EXISTS(SELECT 1 FROM team_suspensions WHERE team_id=c.team_id) THEN','OR EXISTS(SELECT 1 FROM team_suspensions WHERE team_id=c.team_id) OR (c.enrollment<>''open'' AND NOT EXISTS(SELECT 1 FROM challenge_invites WHERE challenge_id=c.id AND user_id=o.buyer_user_id AND revoked_at IS NULL)) THEN'); EXECUTE d;
END $$;
CREATE OR REPLACE FUNCTION public.challenge_order_receipts(_c uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'status',o.status,'currency',o.currency,'total',o.gross_cents,'created_at',o.created_at,'refund_review',EXISTS(SELECT 1 FROM refunds r WHERE r.order_id=o.id AND r.allocation_required AND r.status='succeeded'),'refunds',coalesce((SELECT jsonb_agg(jsonb_build_object('status',r.status,'amount',r.amount_cents,'allocation_required',r.allocation_required) ORDER BY r.created_at) FROM refunds r WHERE r.order_id=o.id),'[]'::jsonb),'lines',(SELECT jsonb_agg(jsonb_build_object('id',i.id,'kind',i.item_type,'name',i.description,'quantity',i.quantity,'unit_cents',i.unit_cents,'refunded_cents',i.refunded_cents) ORDER BY i.created_at,i.id) FROM order_items i WHERE i.order_id=o.id)) ORDER BY o.created_at DESC),'[]'::jsonb) FROM orders o WHERE o.challenge_id=_c AND auth.uid() IS NOT NULL AND (o.buyer_user_id=auth.uid() OR can_manage_challenge(_c)); $$;